let currentModule='all',currentTool=null,history=[];
const optionSets={record:['A','AAAA','CNAME','MX','NS','TXT','PTR'],service:['status','start','stop','restart','reload','enable','enable-now'],mode:['read-only','read-write'],permission:['read','write'],table:['gpt','msdos'],filesystem:['xfs','ext4','ext3'],logkind:['access','error'],mailservice:['postfix','dovecot'],mailprotocol:['smtp','pop3','imap']};
function visibleTools(){const q=$('#search').value.trim().toLowerCase(),action=$('#actionFilter').value;return tools.filter(t=>(currentModule==='all'||t.module===currentModule)&&(action==='all'||t.type===action)&&(`${t.name} ${t.desc} ${t.args}`).toLowerCase().includes(q))}
function render(){const list=visibleTools();$('#resultCount').textContent=`${list.length} tools`;$('#toolList').innerHTML=list.map(t=>`<button type="button" class="tool-item ${currentTool?.id===t.id?'active':''}" data-id="${t.id}"><span class="tool-icon">${modules[t.module].icon}</span><span class="tool-info"><strong>${t.name}</strong><small>${t.desc}</small></span><code>${t.module} ${t.args.split(' ').slice(1,3).join(' ')}</code><span class="tool-arrow">→</span></button>`).join('')||'<div class="empty-result">Không tìm thấy tool phù hợp.</div>'}
function renderField(f){const control=optionSets[f.type]?`<select name="${f.key}">${optionSets[f.type].map(v=>`<option ${v===f.placeholder?'selected':''}>${v}</option>`).join('')}</select>`:`<input type="${f.type==='password'?'password':'text'}" name="${f.key}" placeholder="${f.placeholder}" value="${f.placeholder}" autocomplete="${f.type==='password'?'new-password':'off'}">`;return `<div class="field"><label>${f.label}${f.required?' <em>*</em>':''}</label>${control}${f.help?`<small>${f.help}</small>`:''}</div>`}
function selectTool(id){currentTool=tools.find(t=>t.id===id);if(!currentTool)return;$('#runnerEmpty').classList.add('is-hidden');$('#runnerContent').classList.remove('is-hidden');$('#runner').classList.add('open');$('#runnerModule').textContent=modules[currentTool.module].title;$('#runnerName').textContent=currentTool.name;$('#runnerDesc').textContent=currentTool.desc;$('#fields').innerHTML=currentTool.fields.map(renderField).join('')||'<div class="field"><small>Tool này không cần tham số.</small></div>';$$('#toolForm input, #toolForm select').forEach(e=>e.addEventListener('input',updateCommand));updateCommand();render()}
function updateCommand(){if(!currentTool)return;let args=currentTool.args;currentTool.fields.forEach(f=>{const el=$(`[name="${f.key}"]`),value=el?.value.trim()||'';args=args.replace(`{${f.key}}`,value)});args=args.replace(/\s+/g,' ').trim();$('#commandPreview').textContent=`${$('#dryRun').checked?'NETADMIN_DRY_RUN=1 ':''}/usr/local/bin/netadmin ${args}`;const s=$('#safety');s.classList.toggle('live',!$('#dryRun').checked);s.innerHTML=$('#dryRun').checked?'<span>✓</span><p><b>Chế độ Dry run đang bật</b><small>Lệnh chỉ được in ra, chưa thay đổi hệ thống.</small></p>':'<span>!</span><p><b>Chế độ thực thi đang bật</b><small>Tool có thể thay đổi cấu hình máy chủ.</small></p>'}
function valueOf(key){return $(`[name="${key}"]`)?.value.trim()||''}
function commandArgs(){return currentTool.args.split(/\s+/).map(token=>{const match=token.match(/^\{(.+)\}$/);return match?valueOf(match[1]):token}).filter(Boolean)}
function validateTool(){const missing=currentTool.fields.filter(f=>f.required&&!valueOf(f.key));if(missing.length)throw new Error(`Thiếu thông tin: ${missing.map(f=>f.label).join(', ')}`);if(currentTool.module==='samba'&&currentTool.args.startsWith('samba client')&&valueOf('username')&&!valueOf('password'))throw new Error('Cần nhập mật khẩu khi sử dụng Samba username.')}
function interactionFor(args){const signature=args.slice(0,3).join(' ');if(signature==='storage partition create'||signature==='storage filesystem format'||signature==='storage lvm pv-create'){const target=args[3];const typed=window.prompt(`Tác vụ có thể làm mất dữ liệu.\nNhập chính xác ${target} để tiếp tục:`);if(typed!==target)throw new Error('Đã hủy: target xác nhận không khớp.');return {pty:true,input:`${target}\n`}}if(signature==='storage lvm lv-extend'){if(!window.confirm(`Xác nhận mở rộng ${args[3]}?`))throw new Error('Đã hủy thao tác.');return {pty:true,input:'y\n'}}if(signature==='web site restore'){if(!window.confirm('Khôi phục website từ backup?'))throw new Error('Đã hủy restore.');return {pty:true,input:'y\n'}}if(args[1]==='config'&&args[2]==='rollback'){if(!window.confirm('Khôi phục bản cấu hình gần nhất?'))throw new Error('Đã hủy rollback.');return {pty:true,input:'y\ny\n'}}if(signature==='samba user add'||signature==='ftp user add'||signature==='mail user add')return {pty:true,input:`${valueOf('password')}\n${valueOf('password')}\n`};if(signature==='samba client list'||signature==='samba client copy'){return valueOf('username')?{pty:true,input:`${valueOf('password')}\n`}:{pty:false,input:''}}return {pty:false,input:''}}
function appendTerminal(text,className=''){const span=document.createElement('span');if(className)span.className=className;span.textContent=text;$('#terminal').appendChild(span);$('#terminal').scrollTop=$('#terminal').scrollHeight}
function cockpitAvailable(){return typeof window.cockpit!=='undefined'&&typeof window.cockpit.spawn==='function'}
function setRuntimeStatus(){const card=$('.server-card');if(cockpitAvailable()){card.classList.remove('disconnected');$('#runtimeHost').textContent=location.hostname||'localhost';$('#runtimeStatus').textContent='Cockpit đã kết nối'}else{card.classList.add('disconnected');$('#runtimeHost').textContent='Demo mode';$('#runtimeStatus').textContent='Mở trong Cockpit để chạy tool'}}
function updateCounts(){$$('.nav-item').forEach(b=>{const m=b.dataset.module;b.querySelector('b').textContent=m==='all'?tools.length:tools.filter(t=>t.module===m).length})}
$$('.nav-item').forEach(b=>b.onclick=()=>{currentModule=b.dataset.module;if(currentTool&&currentModule!=='all'&&currentTool.module!==currentModule){currentTool=null;$('#runner').classList.remove('open');$('#runnerContent').classList.add('is-hidden');$('#runnerEmpty').classList.remove('is-hidden')}$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));$('#moduleName').textContent=currentModule==='all'?'TẤT CẢ MODULES':modules[currentModule].title.toUpperCase();$('#moduleTitle').textContent=currentModule==='all'?'Chọn một tool để bắt đầu':`${modules[currentModule].title} tools`;$('.sidebar').classList.remove('open');render()});
$('#toolList').addEventListener('click',event=>{const button=event.target.closest('.tool-item');if(button)selectTool(button.dataset.id)});
$('#search').oninput=render;$('#actionFilter').onchange=render;$('#dryRun').onchange=updateCommand;$('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#closeRunner').onclick=()=>{$('#runner').classList.remove('open');$('#runnerContent').classList.add('is-hidden');$('#runnerEmpty').classList.remove('is-hidden');currentTool=null;render()};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}
$('#copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText($('#commandPreview').textContent)}catch{}toast('Đã sao chép lệnh')};
$('#runBtn').onclick=()=>{let args,interaction;try{validateTool();args=commandArgs();interaction=interactionFor(args)}catch(error){toast(error.message);return}const cmd=$('#commandPreview').textContent;history.unshift({cmd,time:new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})});renderHistory();$('#terminal').innerHTML='';appendTerminal(`$ ${cmd}`,'command');$('#outputDialog').showModal();if(!cockpitAvailable()){appendTerminal('[ERROR] Trang này chưa chạy bên trong Cockpit.','muted');appendTerminal('Cài bằng: sudo ./bin/netadmin ui install\nSau đó mở https://<IP-CENTOS>:9090','muted');$('#exitStatus').textContent='Không có Cockpit runtime';return}const runButton=$('#runBtn');const finish=()=>{runButton.disabled=false;runButton.innerHTML='<span>▶</span> Chạy tool'};runButton.disabled=true;runButton.innerHTML='<span>■</span> Đang chạy…';$('#exitStatus').textContent='Đang chạy';const options={superuser:currentTool.type==='check'?'try':'require',environ:[$('#dryRun').checked?'NETADMIN_DRY_RUN=1':'NETADMIN_DRY_RUN=0']};if(interaction.pty)options.pty=true;else options.err='out';const process=window.cockpit.spawn(['/usr/local/bin/netadmin',...args],options);process.stream(output=>appendTerminal(output));if(interaction.input)process.input(interaction.input);process.then(()=>{appendTerminal('\n[OK] Tool hoàn tất.','ok');$('#exitStatus').textContent='Exit code: 0';finish()}).catch(error=>{appendTerminal(`\n[ERROR] ${error.message||error.problem||'Lệnh thất bại'}`,'muted');$('#exitStatus').textContent=`Lỗi: ${error.exit_status??error.problem??'unknown'}`;finish()})};
function renderHistory(){const list=$('#historyList');list.innerHTML='';if(!history.length){const empty=document.createElement('p');empty.textContent='Chưa có lệnh nào trong phiên này.';list.appendChild(empty);return}history.forEach(item=>{const row=document.createElement('div');row.className='history-row';const time=document.createElement('time');time.textContent=item.time;const command=document.createElement('code');command.textContent=item.cmd;row.append(time,command);list.appendChild(row)})}
$('#historyBtn').onclick=()=>{$('#historyDialog').showModal();renderHistory()};$('#closeOutput').onclick=$('#doneBtn').onclick=()=>$('#outputDialog').close();$('#closeHistory').onclick=()=>$('#historyDialog').close();
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}});
setRuntimeStatus();updateCounts();render();
